<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ApiError, assetCategoryLabels, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import type { ClassificationRecord } from './classification-standards'
import CapabilityAssetPicker from './CapabilityAssetPicker.vue'
interface Model {id:number;name:string;algorithm:string;datasetDigest:string;modelDigest:string;createdAt:string;createdBy:number;trainCount:number;minScore:number;evaluation:{count:number;accuracy:number;macroF1:number;perClass:unknown;confusion:unknown}}
interface Prediction {id:number;modelId:number;assetId:number;assetRevision:number;category:string;scores:{category:string;relativeScore:number}[];matchedTokens:string[];reason:string;createdAt:string}
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>();const base=workspacePath(props.workspace.slug)+'/classification/training/models',owner=computed(()=>props.workspace.role==='owner'),editor=computed(()=>['owner','operator'].includes(props.workspace.role))
const models=ref<Model[]>([]),modelId=ref(''),name=ref(''),examples=ref(''),minScore=ref(0.65),showForm=ref(false),asset=ref<ClassificationRecord>(),prediction=ref<Prediction|null>(null),training=ref(false),predicting=ref(false),error=ref(''),notice=ref('');const busy=computed(()=>training.value||predicting.value);const selected=computed(()=>models.value.find(m=>String(m.id)===modelId.value));const active=new AbortController();let sequence=0
function failed(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=e instanceof Error&&!(e instanceof ApiError)&&!(e instanceof TypeError)?e.message:describeError(e)}
async function load(){try{const r=await request<{items:Model[]}>(base,{signal:active.signal});models.value=r.items;if(!models.value.some(m=>String(m.id)===modelId.value))modelId.value=models.value[0]?String(models.value[0].id):''}catch(e){failed(e)}}
function synthetic(){examples.value=JSON.stringify([{text:'经营收入 销售金额 季度营收',category:'business',split:'train'},{text:'库存数量 采购预算 运营指标',category:'business',split:'train'},{text:'供应商合同 订单统计 财务汇总',category:'business',split:'train'},{text:'联系人姓名 手机号码 电子邮箱',category:'personal',split:'train'},{text:'客户姓名 联系方式 收件地址',category:'personal',split:'train'},{text:'员工姓名 联系电话 通信地址',category:'personal',split:'train'},{text:'季度经营 销售统计',category:'business',split:'evaluation'},{text:'客户联系 邮箱地址',category:'personal',split:'evaluation'}],null,2)}
async function train(){if(!owner.value||busy.value)return;training.value=true;error.value='';try{if(new TextEncoder().encode(examples.value).length>256*1024)throw new Error('训练样本超过256KiB，请减少样本。');const data=JSON.parse(examples.value);if(!Array.isArray(data)||data.length>500)throw new Error('训练样本须为不超过500条的JSON数组。');const model=await request<Model>(base,{method:'POST',body:JSON.stringify({name:name.value,minScore:minScore.value,examples:data}),signal:active.signal});await load();modelId.value=String(model.id);showForm.value=false;examples.value='';notice.value='本地分类模型已训练并保存独立评估结果；模型建议仍需人工核对。'}catch(e){failed(e)}finally{training.value=false}}
async function predict(){if(!asset.value||!selected.value||!editor.value||busy.value)return;const seq=++sequence;predicting.value=true;prediction.value=null;error.value='';try{const r=await request<Prediction>(base+'/'+selected.value.id+'/predict',{method:'POST',body:JSON.stringify({assetId:Number(asset.value.asset.id),revision:asset.value.revision}),signal:active.signal});if(seq===sequence)prediction.value=r}catch(e){if(seq===sequence)failed(e)}finally{if(seq===sequence)predicting.value=false}}
watch([asset,modelId],()=>{sequence++;prediction.value=null;predicting.value=false})
const percent=(n:number)=>Number.isFinite(n)?(n*100).toFixed(1)+'%':'未报告'
onMounted(load);onBeforeUnmount(()=>{active.abort();examples.value=''})
</script>
<template><section class="training-panel"><div class="panel-heading"><div><h2>自有分类模型训练</h2><p>在平台本地训练轻量文本分类模型，记录样本摘要、算法与独立评估集表现。与关键词、正则和格式校验引擎并行提供参考。</p></div><button v-if="owner" class="button button-primary" @click="showForm=!showForm">训练新模型</button></div><p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<form v-if="showForm" class="panel training-form" @submit.prevent="train"><label>模型名称<input v-model="name" maxlength="120" required></label><label>最低采用分数<input v-model.number="minScore" type="number" min="0.5" max="0.99" step="0.01" required></label><label>脱敏样本 JSON<textarea v-model="examples" rows="12" spellcheck="false" required></textarea></label><p>最多500条；至少6条训练样本、2个类别且每类至少2条训练样本，并另留至少2条评估样本。训练与评估不得使用相同文本。category仅business、personal、sensitive_personal；split为train或evaluation。请使用经授权的脱敏文本。</p><div class="actions"><button type="button" class="button" @click="synthetic">填入合成格式示例</button><button type="button" class="button" @click="showForm=false">取消</button><button class="button button-primary" :disabled="busy">{{busy?'训练中…':'本地训练并评估'}}</button></div></form>
<section class="panel training-form"><label>已训练模型<select v-model="modelId"><option value="">请选择模型</option><option v-for="m in models" :key="m.id" :value="String(m.id)">{{m.name}} · #{{m.id}}</option></select></label><p v-if="!models.length">尚无已训练模型。默认规则识别引擎仍可正常使用。</p><template v-if="selected"><dl class="training-metrics"><div><dt>算法</dt><dd>{{selected.algorithm}}</dd></div><div><dt>训练样本</dt><dd>{{selected.trainCount}}</dd></div><div><dt>独立评估样本</dt><dd>{{selected.evaluation.count}}</dd></div><div><dt>评估准确率</dt><dd>{{percent(selected.evaluation.accuracy)}}</dd></div><div><dt>宏平均F1</dt><dd>{{percent(selected.evaluation.macroF1)}}</dd></div></dl><p>结果仅反映这份评估集；不代表所有行业、来源或法律分类的整体准确率。</p><details><summary>每类指标、混淆矩阵与版本证据</summary><pre>{{JSON.stringify({perClass:selected.evaluation.perClass,confusion:selected.evaluation.confusion,datasetDigest:selected.datasetDigest,modelDigest:selected.modelDigest,minScore:selected.minScore,createdAt:selected.createdAt},null,2)}}</pre></details></template></section>
<section class="panel training-form"><h3>对实际资产生成本地参考</h3><CapabilityAssetPicker :workspace="workspace" @change="asset=$event" @session-expired="emit('sessionExpired')"/><p v-if="asset">资产 #{{asset.asset.id}} · {{asset.asset.name}} · 分类修订{{asset.revision}}</p><button class="button button-primary" :disabled="!selected||!asset||!editor||busy" @click="predict">{{busy?'识别中…':'生成本地模型参考'}}</button><article v-if="prediction"><h3>{{assetCategoryLabels[prediction.category]||prediction.category||'未达到采用分数，需人工核对'}}</h3><p>{{prediction.reason}}</p><p>匹配词项：{{prediction.matchedTokens.join('、')||'未匹配到有效词项'}}</p><ul><li v-for="score in prediction.scores" :key="score.category">{{assetCategoryLabels[score.category]||score.category}}：相对分数 {{score.relativeScore.toFixed(3)}}</li></ul><small>模型 #{{prediction.modelId}} · 资产修订{{prediction.assetRevision}} · {{formatDate(prediction.createdAt)}}</small><p>相对分数不是校准概率；不自动写入正式分类，也不认定重要或核心数据。</p></article></section></section></template>
<style scoped>.training-panel{display:grid;gap:18px;min-width:0}.training-panel>.panel-heading{padding:0}.training-panel h2{font-size:18px}.training-panel h3{font-size:15px}.training-panel p,.training-panel li{font-size:12px;line-height:1.85;color:var(--secondary)}.training-form{display:grid;gap:15px;padding:20px}.training-form label{display:grid;gap:7px;font-size:12px}.training-form input,.training-form select,.training-form textarea{font:inherit;border:1px solid var(--input-line);border-radius:6px;padding:9px 10px;background:var(--surface);color:var(--ink);min-width:0;max-width:100%}.training-form>.button{justify-self:start}.training-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;margin:0}.training-metrics dt{font-size:12px;color:var(--secondary)}.training-metrics dd{margin:7px 0 0;font-size:18px;overflow-wrap:anywhere}.training-panel details{font-size:12px}.training-panel summary{cursor:pointer;color:var(--accent)}.training-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto}.training-panel small{font-size:11px;color:var(--secondary)}.actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end}@media(max-width:900px){.training-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
